        val = val & 0x7f;
        while ((curr = source.readUnsignedByte()) >= MAX_BIT) {
            target.writeByte(curr);
            val |= (curr & 0x7f) << shift;
            shift += 7;
        }
        target.writeByte(curr);
        val |= curr << shift;
    }

    target.write(source, val);
