                () ->
                        assertSame(
                                BooleanConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.BOOLEAN())),
                () ->
                        assertSame(
                                BooleanConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.BOOLEAN().bridgedTo(boolean.class))),
                () ->
                        assertSame(
                                ByteConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.TINYINT())),
                () ->
                        assertSame(
                                ByteConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.TINYINT().bridgedTo(byte.class))),
                () ->
                        assertSame(
                                ShortConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.SMALLINT())),
                () ->
                        assertSame(
                                ShortConverter.INSTANCE,
