                () ->
                        assertSame(
                                IntConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(DataTypes.INT())),
                () ->
                        assertSame(
                                IntConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.INT().bridgedTo(int.class))),
                () ->
                        assertSame(
                                LongConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.BIGINT())),
                () ->
                        assertSame(
                                LongConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.BIGINT().bridgedTo(long.class))),
                () ->
                        assertSame(
                                FloatConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.FLOAT())),
                () ->
                        assertSame(
                                FloatConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.FLOAT().bridgedTo(float.class))),
                () ->
                        assertSame(
                                DoubleConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.DOUBLE())),
                () ->
                        assertSame(
                                DoubleConverter.INSTANCE,
