    @Test
    void testBinaryConverters() {
        DataFormatConverter<byte[], byte[]> converter =
                (DataFormatConverter<byte[], byte[]>)
                        DataFormatConverters.getConverterForDataType(DataTypes.BINARY(4));
        byte[] value = new byte[] {1, 2, 3};

        assertAll(
                () ->
                        assertSame(
                                PrimitiveByteArrayConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.VARBINARY(10))),
                () ->
                        assertSame(
                                PrimitiveByteArrayConverter.INSTANCE,
                                DataFormatConverters.getConverterForDataType(DataTypes.BYTES())),
                () -> assertSame(value, converter.toInternal(value)),
                () -> assertArrayEquals(value, converter.toExternal(value)));
    }

    @Test
    void testDecimalConvertersHonorPrecisionAndScale() {
        DataFormatConverter<DecimalData, BigDecimal> bigDecimalConverter =
                (DataFormatConverter<DecimalData, BigDecimal>)
                        DataFormatConverters.getConverterForDataType(DataTypes.DECIMAL(10, 2));
        DataFormatConverter<DecimalData, DecimalData> decimalDataConverter =
                (DataFormatConverter<DecimalData, DecimalData>)
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DECIMAL(18, 6).bridgedTo(DecimalData.class));
        DecimalData decimalData = DecimalData.fromBigDecimal(new BigDecimal("123.456789"), 18, 6);

        assertAll(
                () -> assertInstanceOf(BigDecimalConverter.class, bigDecimalConverter),
                () ->
                        assertEquals(
                                new BigDecimal("12345.67"),
                                bigDecimalConverter.toExternal(
                                        bigDecimalConverter.toInternal(
                                                new BigDecimal("12345.67")))),
                () -> assertInstanceOf(DecimalDataConverter.class, decimalDataConverter),
                () -> assertSame(decimalData, decimalDataConverter.toInternal(decimalData)),
                () -> assertSame(decimalData, decimalDataConverter.toExternal(decimalData)));
    }

