    @Test
    void testArrayDataAndObjectArrayConverters() {
        DataFormatConverter<ArrayData, ArrayData> arrayDataConverter =
                (DataFormatConverter<ArrayData, ArrayData>)
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.STRING()).bridgedTo(ArrayData.class));
        ArrayData arrayData =
                new GenericArrayData(
                        new Object[] {StringData.fromString("a"), null, StringData.fromString("c")});

        DataFormatConverter<ArrayData, String[]> objectArrayConverter =
                (DataFormatConverter<ArrayData, String[]>)
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.STRING()).bridgedTo(String[].class));

        DataFormatConverter<ArrayData, String[]> legacyObjectArrayConverter =
                (DataFormatConverter<ArrayData, String[]>)
                        DataFormatConverters.getConverterForDataType(
                                fromLegacyInfoToDataType(
                                        BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO));

        assertAll(
                () -> assertSame(ArrayDataConverter.INSTANCE, arrayDataConverter),
                () -> assertSame(arrayData, arrayDataConverter.toInternal(arrayData)),
                () -> assertSame(arrayData, arrayDataConverter.toExternal(arrayData)),
                () -> assertInstanceOf(ObjectArrayConverter.class, objectArrayConverter),
                () ->
                        assertArrayEquals(
                                new String[] {"a", null, "c"},
                                objectArrayConverter.toExternal(
                                        objectArrayConverter.toInternal(
                                                new String[] {"a", null, "c"}))),
                () -> assertInstanceOf(ObjectArrayConverter.class, legacyObjectArrayConverter),
                () ->
                        assertArrayEquals(
                                new String[] {"x", "y"},
                                legacyObjectArrayConverter.toExternal(
                                        legacyObjectArrayConverter.toInternal(
                                                new String[] {"x", "y"}))));
    }

