        assertAll(
                () -> assertInstanceOf(MapConverter.class, mapConverter),
                () -> assertEquals(map, mapConverter.toExternal(mapConverter.toInternal(map))),
                () -> assertInstanceOf(MapConverter.class, multisetConverter),
